# area: self_classmethods
# hypothesis: Self-returning fluent methods and a Self-returning classmethod constructor keep the most-derived class through a diamond of mixins, including after chained calls.
from typing import Self, reveal_type


class Base:
    def __init__(self) -> None:
        self.parts: list[str] = []

    def add(self, part: str) -> Self:
        self.parts.append(part)
        return self

    @classmethod
    def empty(cls) -> Self:
        return cls()


class MixA(Base):
    def with_a(self) -> Self:
        return self.add('a')


class MixB(Base):
    def with_b(self) -> Self:
        return self.add('b')


class Final(MixA, MixB):
    def done(self) -> str:
        return ','.join(self.parts)


reveal_type(Final.empty().add('x').with_a().with_b())
reveal_type(Final.empty().add('x').with_a().with_b().done())
f = Final.empty().add('x').with_a().with_b()
print(f.done())
print(MixA.empty().with_a().parts)


def wrong_arg() -> Final:
    return Final.empty().add(1)  # expect-error: int is not str


try:
    print(wrong_arg().done())
except TypeError:
    print('join rejected int')
